export function createBattleScenePacket(state, record) { return record?.narrativePacket || { type: 'BATTLE_SCENE_PACKET', schema: 'battle_v2', scope: state.scope, sessionId: state.sessionId, roundId: record?.roundId, actionId: record?.actionId, preserveUserPrompt: true, committedFacts: record?.adjudication ? [record.adjudication.summary, ...record.adjudication.publicEvents] : [], location: state.scene.location, time: state.scene.time, publicEvents: state.scene.publicEvents, descriptionRequirements: ['描写已提交事实和可见语义状态'], prohibitions: ['禁止复判本轮'], nextDecisionPoint: '等待玩家决策' }; }
export function buildMainStoryRequest(packet, originalPrompt = '') { return { preserveUserPrompt: originalPrompt, injection: packet, contract: { mustNotRejudge: true, source: 'battle_v2' } }; }
export class MainStoryAdapterContract { async generateFromBattlePacket() { throw new Error('主剧情适配器未接入：实现 generateFromBattlePacket(packet, originalPrompt)'); } }
export class MockMainStoryAdapter extends MainStoryAdapterContract { async generateFromBattlePacket(packet, originalPrompt = '') { return { text: `${originalPrompt ? `${originalPrompt}\n` : ''}${packet.committedFacts.join('；')}（模拟主剧情桥接，未调用真实主剧情）` }; } }
